  460: function createArch(object: SceneObject, material: THREE.Material): THREE.Group {
  461:   const [w, h, d] = object.dimensions;
  462:   const group = new THREE.Group();
  463:   const postWidth = w * 0.22;
  464:   const headerHeight = h * 0.22;
  465:   const sideHeight = h - headerHeight;
  466:   const left = new THREE.Mesh(new THREE.BoxGeometry(postWidth, sideHeight, d), material);
  467:   left.position.set(-w / 2 + postWidth / 2, -headerHeight / 2, 0);
  468:   const right = left.clone();
  469:   right.position.x = w / 2 - postWidth / 2;
  470:   const header = new THREE.Mesh(new THREE.BoxGeometry(w, headerHeight, d), material);
  471:   header.position.set(0, sideHeight / 2, 0);
  472:   group.add(left, right, header);
  473:   return group;
  474: }
