  476: function createDoorway(object: SceneObject, material: THREE.Material): THREE.Group {
  477:   const [w, h, d] = object.dimensions;
  478:   const group = new THREE.Group();
  479:   const rail = w * 0.16;
  480:   const left = new THREE.Mesh(new THREE.BoxGeometry(rail, h, d), material);
  481:   left.position.x = -w / 2 + rail / 2;
