  483:   right.position.x = w / 2 - rail / 2;
  484:   const top = new THREE.Mesh(new THREE.BoxGeometry(w, rail, d), material);
  485:   top.position.y = h / 2 - rail / 2;
  486:   group.add(left, right, top);
  487:   return group;
