function triangle(a: Vec3, b: Vec3, c: Vec3, normal: Vec3, triangleId: number): CoverageTriangle {
  const ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const ac = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
