  const vertexCount = view.getUint32(8, true);
  const indexCount = view.getUint32(12, true);
  if (vertexCount === 0 || indexCount === 0 || indexCount % 3 !== 0) {
    throw new Error('Imported mesh asset contains no triangles.');
