import type { Vec3 } from '../../domain/types';
import { createCoverageBitset, setCoverageBit } from './coverageBitset';
import type { SceneAccelerationStructure } from './sceneAcceleration';
import type {
  CoverageOptimizationOptions,
  OriginCandidate,
  OriginEvaluation,
  SurfaceSample,
} from './types';

function smoothstep(edge0: number, edge1: number, value: number): number {
  if (edge0 === edge1) return value >= edge1 ? 1 : 0;
  const t = Math.min(1, Math.max(0, (value - edge0) / (edge1 - edge0)));
  return t * t * (3 - 2 * t);
}

export function evaluateOrigin(
  candidate: OriginCandidate,
  samples: SurfaceSample[],
  acceleration: SceneAccelerationStructure,
  sceneDiagonal: number,
  options: CoverageOptimizationOptions,
): OriginEvaluation {
  const coverageBits = createCoverageBitset(samples.length);
  const visibleBits = createCoverageBitset(samples.length);
  const quality = new Uint8Array(samples.length);
  let usableCount = 0;
  let qualitySum = 0;
  const texelConstant = options.panoramaWidth * options.panoramaHeight / (2 * Math.PI * Math.PI);

  for (let index = 0; index < samples.length; index += 1) {
    const sample = samples[index];
    const offset: Vec3 = [
      sample.position[0] - candidate.position[0],
      sample.position[1] - candidate.position[1],
      sample.position[2] - candidate.position[2],
    ];
    const distance = Math.hypot(offset[0], offset[1], offset[2]);
    if (!(distance > 1e-6)) continue;
    const direction: Vec3 = [offset[0] / distance, offset[1] / distance, offset[2] / distance];
    const towardOrigin: Vec3 = [-direction[0], -direction[1], -direction[2]];
    const facing = Math.max(0,
      sample.geometricNormal[0] * towardOrigin[0]
      + sample.geometricNormal[1] * towardOrigin[1]
      + sample.geometricNormal[2] * towardOrigin[2]);
    const epsilon = Math.max(sceneDiagonal * 1e-5, distance * 1e-4);
    const visible = !acceleration.raycastAny(
      candidate.position,
      direction,
      Math.max(0, distance - epsilon),
      sample.triangleIndex,
      epsilon * 0.25,
    );
    if (!visible) continue;
    setCoverageBit(visibleBits, index);

    const texelDensity = texelConstant * facing / Math.max(distance * distance, 1e-6);
    const angleQuality = smoothstep(options.minimumFacing, 0.55, facing);
    const resolutionQuality = smoothstep(
      options.minimumTexelDensity,
      options.targetTexelDensity,
      texelDensity,
    );
    const sampleQuality = angleQuality * resolutionQuality;
    const qualityByte = Math.max(0, Math.min(255, Math.round(sampleQuality * 255)));
    quality[index] = qualityByte;
    qualitySum += qualityByte;

    if (facing >= options.minimumFacing && texelDensity >= options.minimumTexelDensity) {
      setCoverageBit(coverageBits, index);
      usableCount += 1;
    }
  }

  return {
    position: [...candidate.position],
    coverageBits,
    visibleBits,
    quality,
    individualCoverage: samples.length > 0 ? usableCount / samples.length : 0,
    averageQuality: samples.length > 0 ? qualitySum / (255 * samples.length) : 0,
    clearance: candidate.clearance,
  };
}

import { compareOriginPair } from './coverageBitset';
import type { OriginEvaluation, PairMetrics } from './types';

export interface RankedSecondOrigin {
  evaluation: OriginEvaluation;
  metrics: PairMetrics;
  addedCoverage: number;
}

const COVERAGE_TIE_TOLERANCE = 0.0025;

export function rankSecondOrigins(
  first: OriginEvaluation,
  candidates: OriginEvaluation[],
): RankedSecondOrigin[] {
  return candidates
    .filter((candidate) => candidate !== first)
    .map((evaluation) => {
      const metrics = compareOriginPair(first, evaluation);
      return {
        evaluation,
        metrics,
        addedCoverage: Math.max(0, metrics.unionCoverage - first.individualCoverage),
      };
    })
    .sort((a, b) => {
      const coverageDelta = b.metrics.unionCoverage - a.metrics.unionCoverage;
      if (Math.abs(coverageDelta) > COVERAGE_TIE_TOLERANCE) return coverageDelta;
      const qualityDelta = b.metrics.qualityGain - a.metrics.qualityGain;
      if (Math.abs(qualityDelta) > 1e-8) return qualityDelta;
      const overlapDelta = a.metrics.overlapCoverage - b.metrics.overlapCoverage;
      if (Math.abs(overlapDelta) > 1e-8) return overlapDelta;
      return b.evaluation.clearance - a.evaluation.clearance;
    });
}

export function optimizeSecondOrigin(
  first: OriginEvaluation,
  candidates: OriginEvaluation[],
): RankedSecondOrigin {
  const best = rankSecondOrigins(first, candidates)[0];
  if (!best) throw new Error('No valid secondary origin candidates.');
  return best;
}

import { compareOriginPair, unionCoverage } from './coverageBitset';
import type { OriginEvaluation, PairMetrics } from './types';

export interface RankedOriginPair {
  indexA: number;
  indexB: number;
  evaluationA: OriginEvaluation;
  evaluationB: OriginEvaluation;
  metrics: PairMetrics;
}

const COVERAGE_TIE_TOLERANCE = 0.0025;

function distanceBetween(a: OriginEvaluation, b: OriginEvaluation): number {
  return Math.hypot(
    a.position[0] - b.position[0],
    a.position[1] - b.position[1],
    a.position[2] - b.position[2],
  );
}

export function rankAllPairs(
  evaluations: OriginEvaluation[],
  minimumOriginSeparation: number,
  sampleCount: number,
  maximumResults = Number.POSITIVE_INFINITY,
): RankedOriginPair[] {
  const coarse: Array<{ indexA: number; indexB: number; coverage: number }> = [];
  for (let indexA = 0; indexA < evaluations.length; indexA += 1) {
    for (let indexB = indexA + 1; indexB < evaluations.length; indexB += 1) {
      const evaluationA = evaluations[indexA];
      const evaluationB = evaluations[indexB];
      if (distanceBetween(evaluationA, evaluationB) < minimumOriginSeparation) continue;
      coarse.push({
        indexA,
        indexB,
        coverage: unionCoverage(evaluationA.coverageBits, evaluationB.coverageBits, sampleCount),
      });
    }
  }
  coarse.sort((a, b) => b.coverage - a.coverage);
  const detailed = coarse.slice(0, Math.max(maximumResults * 4, maximumResults)).map((pair) => {
    const evaluationA = evaluations[pair.indexA];
    const evaluationB = evaluations[pair.indexB];
    return {
      indexA: pair.indexA,
      indexB: pair.indexB,
      evaluationA,
      evaluationB,
      metrics: compareOriginPair(evaluationA, evaluationB),
    };
  });
  detailed.sort((a, b) => {
    const coverageDelta = b.metrics.unionCoverage - a.metrics.unionCoverage;
    if (Math.abs(coverageDelta) > COVERAGE_TIE_TOLERANCE) return coverageDelta;
    const qualityDelta = b.metrics.averageQuality - a.metrics.averageQuality;
    if (Math.abs(qualityDelta) > 1e-8) return qualityDelta;
    const contributionA = Math.min(a.metrics.aOnlyCoverage, a.metrics.bOnlyCoverage);
    const contributionB = Math.min(b.metrics.aOnlyCoverage, b.metrics.bOnlyCoverage);
    if (Math.abs(contributionB - contributionA) > 1e-8) return contributionB - contributionA;
    return a.metrics.overlapCoverage - b.metrics.overlapCoverage;
  });
  return detailed.slice(0, maximumResults);
}

export function optimizeJointPair(
  evaluations: OriginEvaluation[],
  minimumOriginSeparation: number,
  sampleCount: number,
): RankedOriginPair {
  const best = rankAllPairs(evaluations, minimumOriginSeparation, sampleCount, 1)[0];
  if (!best) throw new Error('No valid origin pair satisfies the minimum separation.');
  return best;
}

import type { Vec3 } from '../../domain/types';
import type { CoverageBounds, CoverageTriangle } from './types';

interface BvhNode {
  bounds: CoverageBounds;
  left?: BvhNode;
  right?: BvhNode;
  triangleIndices?: number[];
}

const LEAF_TRIANGLE_COUNT = 12;

function triangleBounds(triangle: CoverageTriangle): CoverageBounds {
  return {
    min: [
      Math.min(triangle.a[0], triangle.b[0], triangle.c[0]),
      Math.min(triangle.a[1], triangle.b[1], triangle.c[1]),
      Math.min(triangle.a[2], triangle.b[2], triangle.c[2]),
    ],
    max: [
      Math.max(triangle.a[0], triangle.b[0], triangle.c[0]),
      Math.max(triangle.a[1], triangle.b[1], triangle.c[1]),
      Math.max(triangle.a[2], triangle.b[2], triangle.c[2]),
    ],
  };
}

function unionBounds(indices: number[], boundsByTriangle: CoverageBounds[]): CoverageBounds {
  const min: Vec3 = [Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY, Number.POSITIVE_INFINITY];
  const max: Vec3 = [Number.NEGATIVE_INFINITY, Number.NEGATIVE_INFINITY, Number.NEGATIVE_INFINITY];
  for (const index of indices) {
    const bounds = boundsByTriangle[index];
    for (let axis = 0; axis < 3; axis += 1) {
      min[axis] = Math.min(min[axis], bounds.min[axis]);
      max[axis] = Math.max(max[axis], bounds.max[axis]);
    }
  }
  return { min, max };
}

function centroid(triangle: CoverageTriangle, axis: number): number {
  return (triangle.a[axis] + triangle.b[axis] + triangle.c[axis]) / 3;
}

function buildNode(
  indices: number[],
  triangles: CoverageTriangle[],
  boundsByTriangle: CoverageBounds[],
): BvhNode {
  const bounds = unionBounds(indices, boundsByTriangle);
  if (indices.length <= LEAF_TRIANGLE_COUNT) return { bounds, triangleIndices: indices };
  const extents = [
    bounds.max[0] - bounds.min[0],
    bounds.max[1] - bounds.min[1],
    bounds.max[2] - bounds.min[2],
  ];
  const axis = extents[1] > extents[0]
    ? (extents[2] > extents[1] ? 2 : 1)
    : (extents[2] > extents[0] ? 2 : 0);
  indices.sort((a, b) => centroid(triangles[a], axis) - centroid(triangles[b], axis));
  const midpoint = Math.floor(indices.length / 2);
  return {
    bounds,
    left: buildNode(indices.slice(0, midpoint), triangles, boundsByTriangle),
    right: buildNode(indices.slice(midpoint), triangles, boundsByTriangle),
  };
}

function segmentIntersectsBounds(
  origin: Vec3,
  direction: Vec3,
  maximumDistance: number,
  bounds: CoverageBounds,
): boolean {
  let tMin = 0;
  let tMax = maximumDistance;
  for (let axis = 0; axis < 3; axis += 1) {
    const component = direction[axis];
    if (Math.abs(component) < 1e-12) {
      if (origin[axis] < bounds.min[axis] || origin[axis] > bounds.max[axis]) return false;
      continue;
    }
    const inverse = 1 / component;
    let near = (bounds.min[axis] - origin[axis]) * inverse;
    let far = (bounds.max[axis] - origin[axis]) * inverse;
    if (near > far) [near, far] = [far, near];
    tMin = Math.max(tMin, near);
    tMax = Math.min(tMax, far);
    if (tMin > tMax) return false;
  }
  return tMax >= 0 && tMin <= maximumDistance;
}

/** Double-sided Moller-Trumbore segment/triangle test. */
function segmentIntersectsTriangle(
  origin: Vec3,
  direction: Vec3,
  maximumDistance: number,
  triangle: CoverageTriangle,
  minimumDistance: number,
): boolean {
  const edge1: Vec3 = [
    triangle.b[0] - triangle.a[0],
    triangle.b[1] - triangle.a[1],
    triangle.b[2] - triangle.a[2],
  ];
  const edge2: Vec3 = [
    triangle.c[0] - triangle.a[0],
    triangle.c[1] - triangle.a[1],
    triangle.c[2] - triangle.a[2],
  ];
  const p: Vec3 = [
    direction[1] * edge2[2] - direction[2] * edge2[1],
    direction[2] * edge2[0] - direction[0] * edge2[2],
    direction[0] * edge2[1] - direction[1] * edge2[0],
  ];
  const determinant = edge1[0] * p[0] + edge1[1] * p[1] + edge1[2] * p[2];
  if (Math.abs(determinant) < 1e-10) return false;
  const inverse = 1 / determinant;
  const tVector: Vec3 = [
    origin[0] - triangle.a[0],
    origin[1] - triangle.a[1],
    origin[2] - triangle.a[2],
  ];
  const u = (tVector[0] * p[0] + tVector[1] * p[1] + tVector[2] * p[2]) * inverse;
  if (u < 0 || u > 1) return false;
  const q: Vec3 = [
    tVector[1] * edge1[2] - tVector[2] * edge1[1],
    tVector[2] * edge1[0] - tVector[0] * edge1[2],
    tVector[0] * edge1[1] - tVector[1] * edge1[0],
  ];
  const v = (direction[0] * q[0] + direction[1] * q[1] + direction[2] * q[2]) * inverse;
  if (v < 0 || u + v > 1) return false;
  const distance = (edge2[0] * q[0] + edge2[1] * q[1] + edge2[2] * q[2]) * inverse;
  return distance > minimumDistance && distance < maximumDistance;
}

export interface SceneAccelerationStructure {
  triangles: CoverageTriangle[];
  raycastAny(
    origin: Vec3,
    direction: Vec3,
    maximumDistance: number,
    excludedTriangleIndex?: number,
    minimumDistance?: number,
  ): boolean;
}

/** Compact in-memory BVH with first-hit segment traversal. */
export function buildSceneAcceleration(
  triangles: CoverageTriangle[],
): SceneAccelerationStructure {
  if (triangles.length === 0) throw new Error('Cannot build coverage acceleration without triangles.');
  const boundsByTriangle = triangles.map(triangleBounds);
  const root = buildNode(triangles.map((_, index) => index), triangles, boundsByTriangle);

  return {
    triangles,
    raycastAny(origin, direction, maximumDistance, excludedTriangleIndex, minimumDistance = 1e-6) {
      if (!(maximumDistance > minimumDistance)) return false;
      const stack: BvhNode[] = [root];
      while (stack.length > 0) {
        const node = stack.pop()!;
        if (!segmentIntersectsBounds(origin, direction, maximumDistance, node.bounds)) continue;
        if (node.triangleIndices) {
          for (const triangleIndex of node.triangleIndices) {
            if (triangleIndex === excludedTriangleIndex) continue;
            if (segmentIntersectsTriangle(
              origin,
              direction,
              maximumDistance,
              triangles[triangleIndex],
              minimumDistance,
            )) return true;
          }
          continue;
        }
        if (node.left) stack.push(node.left);
        if (node.right) stack.push(node.right);
      }
      return false;
    },
  };
}

