    expect(PROJECTED_STYLE_GLSL.applyInversePanoYaw).toContain('direction.x * c - direction.z * s');
    expect(PROJECTED_STYLE_GLSL.equirectUvFromDirection).toContain('atan(direction.x, direction.z)');
  });

